import time


P0_EVENTS = {"hard_brake", "safety_pause", "timeout", "round_timeout", "game_end", "answer_correct"}
SCENE_EVENTS = {"environment_change", "speed_overspeed", "driver_tired", "passenger_sleep",
                "driver_distracted", "driver_distracted", "driver_distracted", "passenger_wake", "near_destination", "game_stuck", "near_answer",
                "cabin_laughing", "resume_game", "round_changed", "passenger_inactive"}
PROACTIVE_EVENTS = {"environment_change", "speed_overspeed", "driver_tired", "passenger_inactive"}
SHARE_FIELDS = {"environment", "speed", "driver", "passengers", "progress", "destination", "participation"}
AWAKE_STATES = {"awake", "normal", "active", "happy", "excited", "calm", "清醒", "正常", "普通", "开心", "兴奋", "平静", "大笑", "沉默"}
SEATS = ("front", "rearLeft", "rearRight")


def model_json(value):
    raw = text(value, 50000)
    raw = re.sub(r"<think\b[^>]*>.*?</think\s*>", "", raw, flags=re.I | re.S).strip()
    if re.search(r"<think\b", raw, re.I):
        return {}
    raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I).strip()
    decoder = json.JSONDecoder()
    for match in re.finditer(r"\{", raw):
        try:
            value, end = decoder.raw_decode(raw[match.start():])
            if isinstance(value, dict) and not raw[match.start() + end:].strip():
                return value
        except ValueError:
            continue
    return {}


def canonical_states(snapshot):
    passengers = obj(snapshot.get("passengers"))
    raw = obj(passengers.get("states")) or passengers
    result = {}
    for key, alias in (("driver", "driver"), ("front", "front"), ("rearLeft", "rear_left"), ("rearRight", "rear_right")):
        value = raw.get(key, raw.get(alias))
        if key == "driver" and value is None:
            value = snapshot.get("driver")
        if isinstance(value, dict):
            value = value.get("state") or value.get("mood")
        result[key] = text(value, 30) or "unknown"
    return result


def eligible_seats(snapshot, speaker=None):
    states = canonical_states(snapshot)
    return [seat for seat in SEATS if seat != speaker and states[seat] in AWAKE_STATES]


def scope(snapshot):
    game = obj(snapshot.get("game"))
    return {"game_id": text(snapshot.get("game_id") or game.get("game_id"), 100),
            "round_id": text(snapshot.get("round_id") or game.get("round_id"), 100),
            "scene_version": text(str(snapshot.get("scene_version", "")), 100)}


def participation_snapshot(snapshot):
    raw = obj(snapshot.get("participation"))
    if not raw:
        return {}
    result = {"seat": "front" if raw.get("seat") == "front" else "unknown",
              "invitation_declined": raw.get("invitation_declined") is True}
    for key in ("version", "inactive_duration_ms", "dialogue_silence_ms", "remaining_ms", "real_user_turn_count"):
        value = raw.get(key)
        if isinstance(value, (int, float)) and not isinstance(value, bool) and 0 <= value <= 3600000:
            result[key] = int(value)
    return result


def valid_participation_candidate(snapshot):
    event = obj(snapshot.get("event"))
    state = participation_snapshot(snapshot)
    return (event.get("source") == "participation_monitor" and event.get("seat") == "front"
            and state.get("seat") == "front" and "version" in state
            and state.get("inactive_duration_ms", 0) >= 20000
            and state.get("dialogue_silence_ms", 0) >= 2500
            and state.get("remaining_ms", 0) > 15000 and not state["invitation_declined"]
            and canonical_states(snapshot)["front"] in AWAKE_STATES
            and obj(snapshot.get("game")).get("status") == "playing")


def shareable_snapshot(snapshot):
    car, game = obj(snapshot.get("car")), obj(snapshot.get("game"))
    return {
        "environment": text(car.get("environment"), 100),
        "speed": car.get("speed") if isinstance(car.get("speed"), (int, float)) else None,
        "destination": text(car.get("destination"), 100),
        "driver": canonical_states(snapshot)["driver"],
        "passengers": canonical_states(snapshot),
        "participation": participation_snapshot(snapshot),
        "progress": {key: game.get(key) for key in ("status", "round_index", "total_rounds", "question_count", "max_questions")},
    }


def clean_snapshot(raw):
    source = parse(raw)
    game = obj(source.get("game"))
    # No frontend transcript or player text is allowed to become a second memory.
    result = {key: source[key] for key in ("game_id", "round_id", "scene_version", "car", "driver", "passengers", "event") if key in source}
    result["game"] = {key: game[key] for key in (
        "status", "current_answer", "current_theme", "round_index", "total_rounds", "question_count",
        "max_questions", "covered_fact_keys", "asked_questions", "round_question_plan", "game_id", "round_id",
    ) if key in game}
    result["game"]["asked_questions"] = items(game.get("asked_questions"))[-8:]
    result["game"]["covered_fact_keys"] = items(game.get("covered_fact_keys"))[-24:]
    result["passengers"] = {"states": canonical_states(source), "selected_seat": selected_seat(source)}
    result["participation"] = participation_snapshot(source)
    return result


def empty_knowhow(snapshot, status="not_relevant", speaker=None):
    return {"status": status, "retrieved": [], "eligible_target_seats": eligible_seats(snapshot, speaker)}


def valid_situation(raw, snapshot):
    cached = parse(raw)
    expected = scope(snapshot)
    now = int(time.time() * 1000)
    if not all(expected.values()) or any(cached.get(key) != value for key, value in expected.items()):
        return {}, "scope_mismatch"
    if cached.get("analysis_status") != "ready" or cached.get("usable_for_dialogue") is not True:
        return {}, "not_ready"
    try:
        generated, expires = int(cached["generated_at_ms"]), int(cached["expires_at_ms"])
        if not (generated <= now + 2000 and now < expires <= generated + 60000):
            return {}, "expired"
    except (KeyError, TypeError, ValueError):
        return {}, "invalid_expiry"
    return obj(cached.get("dialogue_context")), "valid"


def scene_envelope(snapshot, context=None, response=None, status="ready", speak=False, usable=False):
    now = int(time.time() * 1000)
    return {"schema_version": 1, "route": "situation", **scope(snapshot),
            "event_id": text(obj(snapshot.get("event")).get("id"), 100),
            "generated_at_ms": now, "expires_at_ms": now + 60000,
            "analysis_status": status, "usable_for_dialogue": usable,
            "dialogue_context": context or {}, "request_proactive_speech": speak,
            "host_response": response}


def valid_environment_change(snapshot):
    event, car = obj(snapshot.get("event")), obj(snapshot.get("car"))
    current, previous = text(car.get("environment"), 100), text(event.get("previous_value"), 100)
    return (event.get("type") == "environment_change" and bool(current) and bool(previous)
            and event.get("value") == current and previous != current
            and obj(snapshot.get("game")).get("status") in {"opening", "playing"})


def environment_rule_response(snapshot, fallback=False):
    environment = text(obj(snapshot.get("car")).get("environment"), 100)
    labels = {"高速路晴天白天": "驶上高速", "高速路晴天深夜": "驶上夜间的高速",
              "高速路雨天白天": "驶上雨中的高速", "城区晴天白天": "来到市区",
              "城区夜晚": "来到夜晚的市区", "城区雨天白天": "来到雨中的市区",
              "车库": "进入车库", "隧道": "进入隧道", "风景区晴天白天": "来到风景区",
              "风景区傍晚": "来到傍晚的风景区", "风景区雪景白天": "来到雪中的风景区",
              "风景区晴天深夜": "来到夜间的风景区"}
    line = "我们{}啦。".format(labels[environment]) if environment in labels else "车外环境变化啦，我们继续。"
    answer = text(obj(snapshot.get("game")).get("current_answer"), 100)
    if answer and answer in line:
        line = "我们继续。"
    result = envelope(snapshot, line, "P1", layer="fallback" if fallback else "rule",
                      rule="environment_announcement", decision="环境变化优先播报；话术由前端排队执行")
    result.update(intent="event", reply_mode="chat_only", strategy="soft_response", target_seat=None,
                  covered_fact_keys=[], applied_knowhow_ids=[], retrieved_knowhow=[], knowhow_status="not_relevant",
                  reason_codes=["environment_change"])
    result["execution"]["actions"] = []
    return result

def main(director_text: str, payload: object) -> dict:
    payload = parse(payload)
    value = model_json(director_text)
    event_data = obj(payload.get("event"))
    event = text(event_data.get("type"), 80)
    utterance = text(payload.get("player_input"), 800)
    priority = text(event_data.get("priority"), 2)
    if priority not in ("P0", "P1", "P2", "P3", "P4"):
        priority = "P2"

    answer = text(obj(payload.get("game")).get("current_answer"), 100)
    line = text(value.get("ai_reply_text"), 1000)
    hint_request = bool(re.search(
        r"(?:给我|给|来点|来|提供|透露|告诉我|帮我|想要|想听|能不能|能给|可不可以|可以|请|求|再给|继续给).{0,8}(?:提示|线索|暗示)|(?:提示|线索|暗示)(?:一下|一点|给我|吧|呢|吗|可以吗|行吗)|提示下|给点(?:提示|线索)",
        utterance,
    ))
    blocked_hint_request = hint_request and payload.get("trigger_type") == "chat" and obj(payload.get("game")).get("status") == "playing"
    errors = []
    validation_reasons = []
    if not value:
        validation_reasons.append("invalid_or_empty_model_json")
    if not line:
        validation_reasons.append("missing_model_reply")
    elif len(line) > 60:
        validation_reasons.append("model_reply_too_long")
    elif answer and answer in line:
        validation_reasons.append("answer_leak_in_model_reply")
    if not line or len(line) > 60 or (answer and answer in line):
        errors.append("missing_long_or_answer_leaking_reply")
        line = "这个问题我还没判断清楚，能换个说法吗？"
    if blocked_hint_request:
        line = "我先不额外给提示哦，可以继续问我一个是或否问题。"

    actions = []
    music_enabled = parse_music_command(utterance) if payload.get("trigger_type") == "chat" else None
    if music_enabled is not None:
        actions.append({
            "type": "music.set_enabled", "enabled": music_enabled,
            "label": "开启背景音乐" if music_enabled else "关闭背景音乐",
            "execution_owner": "frontend",
        })

    result = envelope(
        payload, line, priority,
        rule=event or "realtime_director",
        decision="响应乘客并校验可执行动作",
        guard_status="hint_blocked" if blocked_hint_request else "fallback" if errors else "passed",
        hint_blocked=blocked_hint_request,
        actions=actions,
    )
    if event == "environment_change":
        result["ui_change"].update(cabin_mode="environment_sync", target_seat="all", animation="scene_change", host_emotion="observing")
    elif event in ("driver_tired", "speed_overspeed"):
        result["ui_change"].update(cabin_mode="driver_focus", target_seat="front", animation="cue", host_emotion="care")
    elif event == "passenger_sleep":
        result["ui_change"].update(cabin_mode="soft", animation="soft", host_emotion="care")
    elif event == "near_destination":
        result["ui_change"].update(cabin_mode="final_round", target_seat="all", animation="final", host_emotion="excited")

    intents = ("answer_question", "guess", "smalltalk", "game_related_chat", "repeat_question", "event", "fallback")
    result["intent"] = value.get("intent") if value.get("intent") in intents else "answer_question"
    modes = ("answer_only", "chat_only", "chat_then_bridge")
    result["reply_mode"] = value.get("reply_mode") if value.get("reply_mode") in modes else "answer_only"
    known = {entry["fact_key"] for entry in fact_catalog(payload)}
    covered = {key for key in items(obj(payload.get("game")).get("covered_fact_keys")) if isinstance(key, str)}
    if not errors and result["intent"] in ("answer_question", "guess", "repeat_question"):
        result["covered_fact_keys"] = list(dict.fromkeys(
            key for key in items(value.get("covered_fact_keys"))
            if isinstance(key, str) and key in known and key not in covered
        ))
    if blocked_hint_request:
        result["intent"] = "game_related_chat"
        result["reply_mode"] = "chat_then_bridge"
        result["covered_fact_keys"] = []
    if errors:
        result["intent"] = "fallback"
        result["debug"] = {"validation_errors": errors, "validation_reason_codes": validation_reasons}
    # Describe the branch actually selected, not an invented model reasoning trace.
    if blocked_hint_request:
        layer, rule, summary = "rule", "hint_request_blocked", "拒绝额外提示，邀请继续提问"
    elif errors:
        layer, rule, summary = "fallback", "invalid_model_reply", "回复未通过校验，请乘客换个说法"
    elif event and payload.get("trigger_type") != "chat":
        event_choices = {
            "environment_change": ("environment_response", "回应新的车外环境"),
            "speed_overspeed": ("overspeed_response", "提醒车速超限"),
            "driver_tired": ("driver_care_response", "提醒关注主驾状态"),
            "passenger_sleep": ("sleep_response", "回应乘客睡着事件"),
            "near_destination": ("arrival_response", "提示即将到达，准备收尾"),
        }
        rule, summary = event_choices.get(event, ("event_response", "按事件入口生成回应"))
        layer = "llm"
    else:
        summaries = {"answer_only": "回答本轮问题", "chat_only": "接续闲聊，暂不拉回游戏",
                     "chat_then_bridge": "接住话题，再引导回到游戏"}
        layer, rule, summary = "llm", "reply_mode_selected", summaries[result["reply_mode"]]
    result["decision_trace"].update(layer=layer, matched_rule=rule, strategy_id=rule, decision=summary,
                                    basis={"event_type": event, "intent": result["intent"], "reply_mode": result["reply_mode"]})
    result["decision_trace"]["selection_origin"] = "model_reply_mode" if rule == "reply_mode_selected" else "code_branch"
    if rule == "reply_mode_selected" and value.get("reply_mode") not in modes:
        result["decision_trace"].update(decision="未返回有效回应方式，采用默认回答",
                                         selection_origin="code_default", matched_rule="default_reply_mode")
    if actions:
        result["decision_trace"]["action_authorization"] = "explicit_music_command"
        result["decision_trace"]["decision"] += "；允许音乐开关请求"
    return {"workflow_output": encode(result)}


def parse_music_command(utterance: str):
    target = r"(?:背景音乐|音乐)"
    off = r"(?:关闭|关掉|停止|暂停|静音|不要放|别放|不放|不要播|别播|关)"
    on = r"(?:打开|开启|播放|启动|开一下|放一下|开)"

    # A negated control request is not authorization to change the current state.
    if re.search(r"(?:不要|别|先别).{0,4}(?:关闭|关掉|关|停止|暂停|打开|开启|启动).{0,6}" + target, utterance) or re.search(
        target + r".{0,4}(?:不要|别|先别).{0,4}(?:关闭|关掉|关|停止|暂停|打开|开启|启动)", utterance
    ):
        return None

    if re.search(off + r".{0,6}" + target, utterance) or re.search(target + r".{0,6}" + off, utterance):
        return False
    if re.search(on + r".{0,6}" + target, utterance) or re.search(target + r".{0,6}" + on, utterance):
        return True
    return None

_base_guard_main = main

KNOWN_KNOWHOW = {"HK{:02d}".format(index) for index in range(1, 29)}
STRATEGIES = {
    "direct_answer", "encourage", "invite_collaboration", "soft_response",
    "defer_interruption", "bridge_to_game", "resume_game", "closing",
}
REASON_CODES = {
    "ordinary_yes_no", "repeated_wrong_guesses", "explicit_help_request",
    "independent_thinking_requested", "eligible_collaborator_available",
    "sleeping_passenger_excluded", "environment_change", "smalltalk_continuity",
    "interruption_recovery", "near_destination", "hint_request_blocked",
    "paused_state", "no_relevant_knowhow",
}
STRATEGY_BY_ID = {
    "HK01": {"encourage"}, "HK02": {"encourage", "invite_collaboration"},
    "HK03": {"soft_response"}, "HK04": {"invite_collaboration", "encourage"},
    "HK05": {"soft_response"}, "HK06": {"defer_interruption", "soft_response"},
    "HK07": {"bridge_to_game", "direct_answer", "soft_response"},
    "HK08": {"resume_game", "soft_response"}, "HK09": {"closing", "soft_response"},
}
SEAT_LABELS = {"front": "副驾", "rearLeft": "后排左", "rearRight": "后排右"}


def main(director_text: str, payload: object, director_context: str) -> dict:
    payload = parse(payload)
    base = json.loads(_base_guard_main(director_text, payload)["workflow_output"])
    context = parse(director_context)
    knowhow = obj(context.get("knowhow"))
    game = obj(payload.get("game"))
    retrieved = []
    for record in items(knowhow.get("retrieved"))[:3]:
        if not isinstance(record, dict):
            continue
        knowhow_id = text(record.get("knowhow_id"), 20)
        if knowhow_id in KNOWN_KNOWHOW and all(x["knowhow_id"] != knowhow_id for x in retrieved):
            retrieved.append({"knowhow_id": knowhow_id, "title": text(record.get("title"), 120) or knowhow_id})
    retrieved_ids = {record["knowhow_id"] for record in retrieved}
    status = text(knowhow.get("status"), 20)
    if status not in ("used", "not_relevant", "empty", "failed"):
        status = "failed"
    if status == "used" and not retrieved:
        status = "failed"
    if status != "used":
        retrieved = []
        retrieved_ids = set()

    value = model_json(director_text)
    strategy = text(value.get("strategy"), 40)
    target = value.get("target_seat")
    target = text(target, 30) if isinstance(target, str) else None
    reasons = list(dict.fromkeys(code for code in items(value.get("reason_codes"))
                                 if isinstance(code, str) and code in REASON_CODES))[:5]
    claims = list(dict.fromkeys(code for code in items(value.get("applied_knowhow_ids"))
                                if isinstance(code, str)))[:3]
    eligible = items(knowhow.get("eligible_target_seats"))
    errors = []

    if strategy not in STRATEGIES:
        errors.append("invalid_strategy")
    invalid_claims = [knowhow_id for knowhow_id in claims if knowhow_id not in retrieved_ids]
    if invalid_claims:
        errors.append("unretrieved_knowhow_id")
    if any(not isinstance(seat, str) or seat not in eligible or seat not in SEAT_LABELS for seat in [target] if target):
        errors.append("ineligible_target_seat")
    if strategy == "invite_collaboration" and (not target or target not in eligible):
        errors.append("collaboration_without_eligible_target")
    if target and strategy != "invite_collaboration":
        errors.append("target_without_collaboration_strategy")
    for knowhow_id in claims:
        if knowhow_id in STRATEGY_BY_ID and strategy not in STRATEGY_BY_ID[knowhow_id]:
            errors.append("strategy_conflicts_with_knowhow")
            break

    paused = game.get("status") == "paused"
    if paused and not base.get("execution", {}).get("actions"):
        errors.append("game_paused")

    actual_hint_block = bool(base.get("decision_trace", {}).get("hint_blocked"))
    if not actual_hint_block:
        reasons = [code for code in reasons if code != "hint_request_blocked"]

    if actual_hint_block:
        strategy = "soft_response"
        reasons = ["hint_request_blocked"]
        target = None
        claims = []

    if errors:
        base["ai_reply_text"] = "我先按游戏规则陪你继续，谜底和额外提示先保密。"
        base["intent"] = "fallback"
        base["reply_mode"] = "answer_only"
        base["covered_fact_keys"] = []
        base["passenger_action"] = None
        # Actions in the base output are derived deterministically from explicit
        # music authorization, never copied from the model's free-form fields.
        base["decision_trace"]["guard_status"] = "knowhow_fallback"
        base["debug"] = {**obj(base.get("debug")), "fallback_origin": "knowhow_guard",
                         "validation_errors": list(dict.fromkeys(items(obj(base.get("debug")).get("validation_errors")) + errors))}
        strategy = "soft_response"
        reasons = ["paused_state"] if paused else ["no_relevant_knowhow"]
        target = None
        claims = []

    if paused:
        base["game_status"] = "paused"
        base["is_correct"] = False
        base["covered_fact_keys"] = []
        base["ui_change"]["show_answer"] = False
        base["decision_trace"]["guard_status"] = "paused_no_progress"
        if "paused_state" not in reasons:
            reasons.append("paused_state")
        strategy = "soft_response"
        target = None
        claims = []

    if not actual_hint_block and re.search(
        r"(?:不能|不可以|不允许|不让|不提供|不主动给).{0,10}(?:提示|线索|暗示)|(?:提示|线索|暗示).{0,10}(?:不能|不可以|不允许|不让|不提供)",
        text(base.get("ai_reply_text"), 1000),
    ):
        if strategy == "invite_collaboration" and target in eligible and target in SEAT_LABELS:
            base["ai_reply_text"] = "我陪你一起想。要不要请{}也来帮忙？".format(SEAT_LABELS[target])
        else:
            base["ai_reply_text"] = "我陪你一起换个角度想想，咱们慢慢来。"

    base["knowhow_status"] = status
    base["retrieved_knowhow"] = retrieved
    base["strategy"] = strategy if strategy in STRATEGIES else "soft_response"
    base["target_seat"] = target
    base["reason_codes"] = reasons
    base["applied_knowhow_ids"] = claims
    base["decision_trace"]["decision"] = "策略：{}；依据：{}".format(
        base["strategy"], "、".join(reasons) if reasons else "无附加经验依据"
    )
    base["decision_trace"]["strategy_id"] = base["strategy"]
    if errors:
        base["decision_trace"]["matched_rule"] = "knowhow_output_guard"
    if target:
        base["decision_trace"]["decision"] += "；协作目标：{}".format(SEAT_LABELS[target])
    if claims:
        base["decision_trace"]["decision"] += "；采用经验：{}".format("、".join(claims))
    return {"workflow_output": encode(base)}

