FEEDBACK_IDS = {"HK10", "HK11", "HK12", "HK13", "HK14", "HK17"}
ALL_SEATS = {"driver", "front", "rearLeft", "rearRight"}


def count(value, maximum=100):
    return int(value) if isinstance(value, (int, float)) and not isinstance(value, bool) and 0 <= value <= maximum else 0


def host_preferences(snapshot):
    raw = obj(snapshot.get("host_preferences"))
    return {key: raw[key] if isinstance(raw.get(key), bool) else default
            for key, default in (("praise", True), ("brief", False), ("invitations", True), ("independent", False))}


def performance_snapshot(snapshot):
    raw = obj(snapshot.get("performance"))
    result = {key: count(raw.get(key)) for key in ("completed_rounds", "team_correct", "streak_count", "consecutive_unsolved")}
    result["per_seat_correct"] = {seat: count(obj(raw.get("per_seat_correct")).get(seat)) for seat in ALL_SEATS}
    result["streak_seat"] = raw.get("streak_seat") if raw.get("streak_seat") in ALL_SEATS else None
    result["recent_results"] = [{"round_index": count(row.get("round_index")),
                                 "correct_seat": row.get("correct_seat") if row.get("correct_seat") in ALL_SEATS else None}
                                for row in items(raw.get("recent_results"))[-3:] if isinstance(row, dict)]
    last = obj(raw.get("last_result"))
    result["last_result"] = {"round_index": count(last.get("round_index")),
                             "correct_seat": last.get("correct_seat") if last.get("correct_seat") in ALL_SEATS else None,
                             "contributors": list(dict.fromkeys(seat for seat in items(last.get("contributors")) if seat in ALL_SEATS))}
    return result


def feedback_snapshot(snapshot):
    raw = obj(snapshot.get("host_feedback"))
    return {"id": text(raw.get("id"), 140), "subject_seat": raw.get("subject_seat") if raw.get("subject_seat") in ALL_SEATS else None,
            "selected_id": text(raw.get("selected_id"), 10),
            "candidate_ids": [key for key in items(raw.get("candidate_ids"))[:3] if key in FEEDBACK_IDS],
            "contributors": list(dict.fromkeys(seat for seat in items(raw.get("contributors")) if seat in ALL_SEATS)),
            **{key: count(raw.get(key)) for key in ("team_correct", "personal_correct", "streak_count", "previous_unsolved")}}


def valid_result_feedback(snapshot):
    event, game = obj(snapshot.get("event")), obj(snapshot.get("game"))
    feedback, performance = feedback_snapshot(snapshot), performance_snapshot(snapshot)
    subject = feedback["subject_seat"]
    if (event.get("type") != "post_result_feedback" or event.get("source") != "performance_monitor"
            or game.get("status") != "victory" or not host_preferences(snapshot)["praise"]
            or not feedback["id"] or subject not in ALL_SEATS
            or performance["last_result"]["correct_seat"] != subject
            or performance["last_result"]["round_index"] != game.get("round_index")
            or feedback["team_correct"] != performance["team_correct"]
            or feedback["personal_correct"] != performance["per_seat_correct"][subject]
            or feedback["streak_count"] != performance["streak_count"]):
        return False
    recent = performance["recent_results"]
    valid = set()
    if feedback["team_correct"] == 6:
        valid.add("HK10")
    if performance["streak_seat"] == subject and feedback["streak_count"] in (2, 3):
        valid.add("HK11")
    if feedback["personal_correct"] == 6:
        valid.add("HK12")
    if feedback["personal_correct"] == 1:
        valid.add("HK13")
    if feedback["previous_unsolved"] >= 2 and len(recent) == 3 and all(row["correct_seat"] is None for row in recent[:-1]):
        valid.add("HK14")
    if len(feedback["contributors"]) >= 2 and set(feedback["contributors"]) == set(performance["last_result"]["contributors"]):
        valid.add("HK17")
    return bool(feedback["candidate_ids"] and feedback["selected_id"] in feedback["candidate_ids"]
                and set(feedback["candidate_ids"]).issubset(valid))


_experience_clean_snapshot = clean_snapshot


def clean_snapshot(raw):
    source = parse(raw)
    current = _experience_clean_snapshot(raw)
    current.update(host_preferences=host_preferences(source), performance=performance_snapshot(source),
                   host_feedback=feedback_snapshot(source))
    return current


_experience_shareable_snapshot = shareable_snapshot


def shareable_snapshot(snapshot):
    return {**_experience_shareable_snapshot(snapshot), "performance": performance_snapshot(snapshot),
            "host_preferences": host_preferences(snapshot), "feedback": feedback_snapshot(snapshot)}

def main(payload: str, director_context: str) -> dict:
    current, context = parse(payload), parse(director_context)
    event = obj(current.get("event"))
    kind = text(event.get("type"), 80)
    plan, known = obj(context.get("analysis_plan")), obj(context.get("knowhow"))
    valid = plan.get("analysis_valid") is True
    speaking = valid and plan.get("proactive_speech") is True and context.get("proactive_allowed") is True
    feedback = kind == "post_result_feedback"
    participation = kind == "passenger_inactive"
    if feedback:
        valid = valid and valid_result_feedback(current)
        speaking = speaking and valid
    if participation:
        speaking = speaking and valid_participation_candidate(current)
    fields = [key for key in items(plan.get("selected_fields")) if key in SHARE_FIELDS]
    public = shareable_snapshot(current)
    records = []
    for row in items(known.get("retrieved"))[:3]:
        if not isinstance(row, dict) or not re.fullmatch(r"HK(?:0[1-9]|1[0-9]|2[0-8])", text(row.get("knowhow_id"), 10)):
            continue
        record = parse(row.get("content"))
        rules = {key: record[key] for key in ("recommended_strategy", "recommended_actions", "exceptions") if key in record}
        records.append({"knowhow_id": row["knowhow_id"], "title": text(row.get("title"), 120), "content": encode(rules)[:1200]})
    strategy = ("encourage" if feedback or kind in {"game_stuck", "near_answer"} else
                "invite_collaboration" if participation else "closing" if kind == "near_destination" else "soft_response")
    target = "front" if participation and speaking else None
    guidance = {"strategy": strategy, "target_seat": target, "event_type": kind,
                "reason_codes": ["achievement_feedback" if feedback else kind], "applied_knowhow_ids": []}
    references = {"status": "used" if records else known.get("status", "not_relevant"), "retrieved": records,
                  "eligible_target_seats": ["front"] if target else eligible_seats(current)}
    dialogue = {"selected_snapshot": {key: public[key] for key in fields}, "guidance": guidance, "knowhow": references}
    if feedback:
        dialogue["feedback"] = feedback_snapshot(current)
    usable = valid and plan.get("share_context") is True and bool(fields) and not feedback and not participation
    result = scene_envelope(current, dialogue if valid else {}, status="ready" if valid else "failed", speak=speaking, usable=usable)
    trace = envelope(current, "", event.get("priority", "P3"), layer="rule" if context.get("priority_fast_path") or feedback else "llm",
                     rule=kind, decision="情境分析完成，申请Chatflow回应" if speaking else "情境分析完成，本次静默")
    result.update(event_type=kind, host_response=None, strategy=strategy, target_seat=target,
                  reason_codes=guidance["reason_codes"], applied_knowhow_ids=[], knowhow_status=references["status"],
                  retrieved_knowhow=known.get("retrieval_hits", [{"knowhow_id": row["knowhow_id"], "title": row["title"]} for row in records]),
                  perception=trace["perception"], decision_trace=trace["decision_trace"],
                  execution={"kind": "plan", "actions": [], "timing": {"owner": "frontend"}, "fallback": "silent"})
    result["decision_trace"].update(guard_status="passed" if valid else "analysis_invalid", strategy_id=strategy,
                                    selection_origin="priority_rule" if context.get("priority_fast_path") else "analysis_plan")
    if feedback:
        result["feedback_id"] = feedback_snapshot(current)["id"]
    if participation:
        result["participation_version"] = participation_snapshot(current).get("version")
        result["expires_at_ms"] = result["generated_at_ms"] + 10000
    return {"scene_output": encode(result)}

import json
import re


def obj(value):
    return value if isinstance(value, dict) else {}


def text(value, limit=500):
    return value.strip()[:limit] if isinstance(value, str) else ""


def items(value):
    return value if isinstance(value, list) else []


def parse(value):
    if isinstance(value, dict):
        return value
    try:
        return obj(json.loads(value))
    except (ValueError, TypeError):
        return {}


def model_json(value):
    value = text(value, 50000)
    start, end = value.find("{"), value.rfind("}")
    return parse(value[start:end + 1]) if start >= 0 and end > start else {}


def encode(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def selected_seat(payload):
    passengers, interaction = obj(payload.get("passengers")), obj(payload.get("interaction"))
    raw = passengers.get("selected_seat") or interaction.get("current_speaker") or passengers.get("selected_seat_label")
    aliases = {"主驾": "driver", "副驾": "front", "后排左": "rearLeft", "后排右": "rearRight", "rear_left": "rearLeft", "rear_right": "rearRight"}
    raw = text(raw)
    raw = aliases.get(raw, raw)
    return raw if raw in ("driver", "front", "rearLeft", "rearRight") else "front"


def fact_catalog(payload):
